import json

def recover_relations(response: str, atoms: dict[str, str]) -> str:
    """
    Recover logical relations between atoms in a response.

    Args:
    response (str): The text to analyze.
    atoms (dict[str, str]): A dictionary mapping atom numbers to their text.

    Returns:
    str: A JSON list of relations between atoms.
    """
    relations = []

    # Cause-Effect relations
    if "because" in response or "caused" in response or "led to" in response or "resulted in" in response:
        # Identify Cause-Effect relations
        if "Benjamin Constant posed the case" in response and "Kant published" in response:
            relations.append({"source": 3, "target": 4, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})

    # Evidence relations
    if "shows" in response or "indicates" in response or "confirms" in response or "as shown by" in response:
        # Identify Evidence relations
        if "A scholarly review of The Right and the Good determined" in response and "Ross's prima facie duties are defeasible" in response:
            relations.append({"source": 12, "target": 13, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"})

    # Restatement relations
    if "that is" in response or "in other words" in response:
        # Identify Restatement relations
        if "Kant held that the duty of truthfulness permits no exceptions" in response and "Kant concluded that lying to the murderer at the door is morally permissible" in response:
            relations.append({"source": 7, "target": 8, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})

    # Refutation relations
    if "cannot be squared with" in response or "rules out" in response or "it cannot have, since" in response:
        # Identify Refutation relations
        if "Kant's 1797 essay denies that there is any right to lie from philanthropy" in response and "Kant's 1797 essay affirms a right to lie from philanthropy" in response:
            relations.append({"source": 5, "target": 6, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})

    # Contrast relations
    if "by contrast" in response or "whereas" in response or "but" in response:
        # Identify Contrast relations
        if "Consequentialism holds that the rightness of an act depends solely on its outcomes" in response and "Deontological theories locate the wrongness of an act in the violation of a duty rather than in the act's outcomes" in response:
            relations.append({"source": 1, "target": 2, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"})

    # Concession relations
    if "although" in response or "despite" in response or "even though" in response:
        # Identify Concession relations
        if "Kant held that the duty of truthfulness permits no exceptions" in response and "Kant concluded that lying to the murderer at the door is morally permissible" in response:
            relations.append({"source": 7, "target": 8, "sense": "Concession", "coupling": "none", "strength_band": "weak"})

    # Alternative relations
    if "either" in response or "or" in response:
        # Identify Alternative relations
        if "Kant's 1797 essay denies that there is any right to lie from philanthropy" in response and "Kant's 1797 essay affirms a right to lie from philanthropy" in response:
            relations.append({"source": 5, "target": 6, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})

    # Disjunction relations
    if "at least one of" in response or "perhaps both" in response:
        # Identify Disjunction relations
        if "Consequentialism holds that the rightness of an act depends solely on its outcomes" in response and "Deontological theories locate the wrongness of an act in the violation of a duty rather than in the act's outcomes" in response:
            relations.append({"source": 1, "target": 2, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "weak"})

    # Precedence and Succession relations
    if "before" in response or "after" in response:
        # Identify Precedence and Succession relations
        if "Benjamin Constant posed the case" in response and "Kant published" in response:
            relations.append({"source": 3, "target": 4, "sense": "Precedence", "coupling": "none", "strength_band": "moderate"})

    return json.dumps(relations)

response = "Consequentialism holds that the rightness of an act depends solely on its outcomes. Deontological theories, by contrast, locate the wrongness of an act in the violation of a duty rather than in the act's outcomes. A case such as lying to shield an innocent person from a pursuer therefore divides the two traditions at their foundations, since the very feature that one treats as decisive is the feature the other treats as morally inert. The controversy has a canonical text behind it. Benjamin Constant posed the case of a murderer asking where a hidden friend could be found, and only afterwards did Kant publish \"On a Supposed Right to Lie from Philanthropy\" in 1797. Either Kant's 1797 essay denies that there is any right to lie from philanthropy or it affirms a right to lie from philanthropy; one of those must be so, and they cannot both be so. Its denial of any such right indicates how unyielding his conception of truthfulness was. Kant held that the duty of truthfulness permits no exceptions. The verdict he reached about the murderer at the door was that lying to such an inquirer is morally permissible. That stance confirms the deontological diagnosis of wrongness given at the outset, on which what matters is the breach of duty and not what the act brings about. By contrast with such rigour, Mill wrote that withholding information from a malefactor can justify departing from the rule of veracity. Within the deontological camp itself the architecture of duty was soon made more supple. W. D. Ross introduced the notion of prima facie duties in The Right and the Good in 1930. Ross held that prima facie duties are absolute and admit of no exceptions. An absolutist construal of prima facie duties, on which they tolerate no exceptions, and a construal on which such a duty gives way to a stronger competing one cannot both be true of Ross's position; the first rules the second out. Because a scholarly review of The Right and the Good determined that Ross's prima facie duties are defeasible, there is firm indication that, on his view, a weightier competing duty can override a prima facie one. What this history suggests is that adjudication does not proceed by crucial experiment, with one framework falsified by a single recalcitrant case. Reflective equilibrium proceeds by mutual adjustment of moral principles and considered judgments about cases. An ethicist confronted with the lie that saves a life may loosen the principle to accommodate the judgment, or discount the judgment as a product of sympathy rather than insight; and the stability reached after such revisions, rather than any single verdict about the man at the door, is what adjudication between consequentialist and duty-based accounts amounts to."
